mapper.update:
UPDATE course_assignments
   SET title = #{title}, title_edited = 1, version = version + 1
 WHERE assignment_id = #{assignmentId} AND user_id = #{userId} AND version = #{version}

UPDATE course_assignments
   SET completed_at = #{completedAt}, version = version + 1
 WHERE assignment_id = #{assignmentId} AND user_id = #{userId} AND version = #{version}

UPDATE course_assignments
   SET course_id = COALESCE(course_id, #{courseId}), topic_id = COALESCE(topic_id, #{topicId})
 WHERE assignment_id = #{assignmentId}
